package vn.rtr.aeris.crew02;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;
/** Bounded append/fsync audit, no authority restoration. Verified before any append. */
public final class CrewAudit02{
 private final File f;private String head="";private int n=0;private long bytes=0;private boolean failed=false;private final List<Map<String,Object>>trusts=new ArrayList<>();
 public CrewAudit02(File root)throws Exception{if(!root.isDirectory()&&!root.mkdirs())throw new IOException("CREW_AUDIT_DIR");f=new File(root,"audit.jsonl");if(Files.isSymbolicLink(f.toPath()))throw new IOException("CREW_AUDIT_SYMLINK");if(f.exists()){if(f.length()>4194304)throw new IOException("CREW_AUDIT_QUOTA");byte[]all=Files.readAllBytes(f.toPath());if(all.length>0&&all[all.length-1]!=10)throw new IOException("CREW_AUDIT_TORN_HOLD");for(String l:new String(all,StandardCharsets.UTF_8).split("\n")){if(l.isEmpty())continue;Map<String,Object>q=StrictJson02.parse(l.getBytes(StandardCharsets.UTF_8));StrictJson02.exact(q,"n","previous","kind","dataBase64","sha256");long v=StrictJson02.integer(q,"n");String prev=StrictJson02.text(q,"previous"),kind=StrictJson02.text(q,"kind"),data=StrictJson02.text(q,"dataBase64");String h=sha((v+"\n"+prev+"\n"+kind+"\n"+data).getBytes(StandardCharsets.UTF_8));if(v!=n+1||!prev.equals(head)||!h.equals(q.get("sha256")))throw new IOException("CREW_AUDIT_CHAIN_HOLD");n++;head=h;if(kind.equals("TRUST"))trusts.add(StrictJson02.parse(Base64.getDecoder().decode(data)));}bytes=all.length;}}
 public static String sha(byte[]b)throws Exception{StringBuilder s=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}
 public synchronized void append(String kind,Map<String,Object>data)throws Exception{if(failed)throw new IOException("CREW_AUDIT_HOLD");byte[]b=Data97.json(data).getBytes(StandardCharsets.UTF_8);if(b.length>8192||n>=4096||f.getParentFile().getUsableSpace()<33554432L)throw new IOException("CREW_AUDIT_QUOTA_OR_DISK");String encoded=Base64.getEncoder().encodeToString(b),h=sha(((n+1)+"\n"+head+"\n"+kind+"\n"+encoded).getBytes(StandardCharsets.UTF_8));byte[]line=(Data97.json(Data97.m("n",n+1,"previous",head,"kind",kind,"dataBase64",encoded,"sha256",h))+"\n").getBytes(StandardCharsets.UTF_8);if(bytes+line.length>4194304)throw new IOException("CREW_AUDIT_QUOTA");try(FileOutputStream out=new FileOutputStream(f,true)){out.write(line);out.getFD().sync();}catch(Exception e){failed=true;throw e;}n++;head=h;bytes+=line.length;}
 public synchronized void trust(long epoch,String digest)throws Exception{if(failed)throw new IOException("CREW_AUDIT_HOLD");long maximum=0;String lastDigest="";for(Map<String,Object>t:trusts){long old=StrictJson02.integer(t,"epoch");if(old>=maximum){maximum=old;lastDigest=StrictJson02.text(t,"digest");}}if(epoch<maximum||epoch==maximum&&!digest.equals(lastDigest))throw new IOException("CREW_TRUST_ROLLBACK_OR_REWRITE");if(epoch==maximum)return;Map<String,Object>t=Data97.m("epoch",epoch,"digest",digest);append("TRUST",t);trusts.add(t);}

 public synchronized Map<String,Object>summary(){return Data97.m("records",n,"head",head,"bytes",bytes,"authorityRestorable",false);}
}
